function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();

  // Define colors for the ground, the sky, and the hills
  const gColor = "#3498db"; // Green
  const sColor = "#4CAF50"; // Yellow
  const hColor = "#f0ffff"; // Gold

  // Calculate the position of the sun
  const sunX = width * Math.sin(frameCount / 360); // Position in x-axis
  const sunY = height * Math.cos(frameCount / 360); // Position in y-axis

  // Calculate the sunset effect
  const sunsetFrequency = 0.1;
  const sunsetAmplitude = 0.5;

  // Draw the ground
  brush.beginShape(0.3);
  brush.vertex(sunX, sunY);
  brush.vertex(width - sunX, sunY);
  brush.vertex(width, sunY);
  brush.vertex(sunX, sunY);
  brush.endShape(true);

  // Draw the sky
  brush.beginShape(0.3);
  brush.vertex(sunX, sunY);
  brush.vertex(sunX + sunsetFrequency * 10, sunY);
  brush.vertex(sunX + sunsetFrequency * 10, sunY + sunsetAmplitude * 5);
  brush.vertex(sunX, sunY + sunsetAmplitude * 5);
  brush.vertex(sunX - sunsetFrequency * 10, sunY);
  brush.vertex(sunX - sunsetFrequency * 10, sunY + sunsetAmplitude * 5);
  brush.vertex(sunX, sunY);
  brush.endShape(true);

  // Draw the hills
  brush.beginShape(0.3);
  brush.vertex(width - sunsetFrequency * 10, sunY);
  brush.vertex(sunX + sunsetFrequency * 10, sunY + sunsetAmplitude * 5);
  brush.vertex(sunX - sunsetFrequency * 10, sunY + sunsetAmplitude * 5);
  brush.vertex(sunX - sunsetFrequency * 10, sunY + sunsetAmplitude * 5);
  brush.vertex(width - sunsetFrequency * 10, sunY);
  brush.endShape(true);

  // Draw the sun
  brush.circle(sunX, sunY, 60);
}

function frameRate() {
  // Adjust the sunset effect speed
  return sunsetFrequency * 0.1;
}

