  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#f4efe4");
  brush.circle(200, 150, 60);

  // sunset effect
  const sunset = "#e26e72";
  const sunX = 200;
  const sunY = 200;

  // Calculate the angles between the sun and each hill
  for (let i = 0; i < 3; i++) {
    const angle = atan((sunY - i * 150) / (sunX - i * 150)) * (180 / Math.PI);
    const x = sunX + Math.cos(angle) * 150;
    const y = sunY + Math.sin(angle) * 150;
    brush.vertex(x, y);
  }

  // Draw the edges of the hills
  for (let i = 0; i < 3; i++) {
    const angle = atan((i * 150 - sunsetY) / (i * 150 - sunsetX)) * (180 / Math.PI);
    const x = sunsetX + Math.cos(angle) * 150;
    const y = sunsetY + Math.sin(angle) * 150;
    brush.circle(x, y, 5);
  }
}

