function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Draw a red disc
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);

  // Draw a sunset disc
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Create a detailed sunset pattern
  var centerX = 200;
  var centerY = 200;
  var angle = 0;

  // Define the number of points for the pattern
  var numPoints = 50;
  var stepSize = 0.1;

  // Loop through each point in the pattern
  for (var i = 0; i < numPoints; i++) {
    // Calculate the position of the point
    var x = centerX + i * stepSize;
    var y = centerY - i * stepSize;

    // Increase the angle for a smooth pattern
    angle += 0.001;

    // Fill the point with a texture
    brush.noStroke();
    brush.fillTexture(0.5, 0.4);
    brush.fill("#7fb2d9", 180);
    brush.beginShape(0.3);
    brush.vertex(x, y);
    brush.vertex(x + 10, y);
    brush.vertex(x + 20, y);
    brush.vertex(x + 30, y);
    brush.vertex(x, y);
    brush.endShape(true);
  }
}

