  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Lighthouse design follows a straight path towards the rocky shore.
  brush.vertex(300, 0); // Right side of the side
  brush.vertex(200, 200); // Bottom of the side
  brush.vertex(200, 0); // Bottom of the side
  brush.vertex(200, 200); // Bottom of the side
  brush.vertex(300, 0); // Right side of the side

  // Begin a new shape for the lighthouse and apply texture.
  brush.beginShape(0.3);
  brush.vertex(300, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(300, 200);
  brush.endShape(true);
  brush.texture("lighthouse.jpg");

  // Finally, start a new shape for the details.
  brush.beginShape(0.3);
  brush.vertex(300, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(300, 200);
  brush.endShape(true);
}

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);

  // Center of the lighthouse
  const x = width / 2;
  const y = height / 2;

  // Adjust lighthouse proportions
  const LIFETIME = 20; // 20 seconds total
  const LIGHTING = 0.75; // Light intensity (0-1)
  const PERSISTENT = 0.05; // Lighthouse's opacity (0-1)

  // Time elapsed
  const time = millis() / 1000; // Convert milliseconds to seconds

  // Calculate position for the light
  const lightX = x + LIFETIME * Math.cos(time * LIGHTING) * PERSISTENT;
  const lightY = y + LIFETIME * Math.sin(time * LIGHTING) * PERSISTENT;

  // Draw the lighthouse
  brush.beginShape(0.3);
  brush.vertex(lightX, lightY);
  brush.vertex(lightX + 50, lightY);
  brush.vertex(lightX + 100, lightY + 50);
  brush.vertex(lightX, lightY + 100);
  brush.endShape(true);

  // Fill the entire canvas with white
  fill(255, 255, 255);
  stroke(0, 0, 0);
  rect(0, 0, width, height);
}

