  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);

  // Draw the bottom half of the lighthouse
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#d1495b", 220);
  brush.beginShape(0.3);
  brush.vertex(400, 200);
  brush.vertex(400, height);
  brush.vertex(0, height);
  brush.endShape(true);

  // Draw the lighthouse's top edge
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#d3adec", 140);
  brush.beginShape(0.3);
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 180);
  brush.vertex(200, 180);
  brush.vertex(200, 150);
  brush.vertex(400, 150);
  brush.endShape(true);

  // Add a text to describe the lighthouse
  brush.text("Lighthouse", 300, 100, 25, "#000000");
  brush.text("Mountainside", 300, 120, 25, "#000000");

  // Add an image for the lighthouse
  brush.image("lighthouse.png", 100, 100);
}

