function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Backdrop: rocky shore
  push();
  brush.set("blue");
  brush.arc(0, 0, width, height, 0, PI * 2);
  pop();

  // Lighthouse
  push();
  brush.set("yellow");
  brush.beginShape(2);
  brush.vertex(width / 4, 0);
  brush.vertex(width / 2, height / 2);
  brush.vertex(3 * width / 4, height / 2);
  brush.vertex(0, height);
  brush.endShape(true);

  // Front of the lighthouse
  push();
  brush.set("red");
  brush.arc(0, height / 4, width / 2, height / 4, 0, PI * 2);
  pop();

  // Display the lighthouse
  push();
  strokeWeight(2);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  fill("#d4495b");
  rect(width / 2, height / 4, width / 2, height / 4);
  pop();

  // Sky and ground
  push();
  brush.set("sky");
  brush.arc(0, 0, width, height, 0, PI * 2);
  pop();
  push();
  brush.set("ground");
  brush.arc(0, 0, width / 2, height / 2, 0, PI * 2);
  pop();
}

