  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Make a mountain
  var mountainTop = 150;
  var mountainBottom = 250;
  var mountainLeft = 250;
  var mountainRight = 150;

  // Draw the left side
  brush.beginShape(0.3);
  brush.vertex(mountainLeft, mountainTop);
  brush.vertex(mountainLeft, mountainBottom);
  brush.vertex(mountainRight, mountainBottom);
  brush.vertex(mountainRight, mountainTop);
  brush.endShape(true);

  // Draw the right side
  brush.beginShape(0.3);
  brush.vertex(mountainRight, mountainTop);
  brush.vertex(mountainRight, mountainBottom);
  brush.vertex(mountainLeft, mountainBottom);
  brush.vertex(mountainLeft, mountainTop);
  brush.endShape(true);

  // Draw the top
  brush.beginShape(0.3);
  brush.vertex(mountainTop, mountainRight);
  brush.vertex(mountainTop, mountainLeft);
  brush.vertex(mountainBottom, mountainLeft);
  brush.vertex(mountainBottom, mountainRight);
  brush.endShape(true);

  // Draw the bottom
  brush.beginShape(0.3);
  brush.vertex(mountainBottom, mountainRight);
  brush.vertex(mountainBottom, mountainLeft);
  brush.vertex(mountainTop, mountainLeft);
  brush.vertex(mountainTop, mountainRight);
  brush.endShape(true);
}

