function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);

  // Outer circle
  for (let i = 0; i < 40; i++) {
    brush.beginShape(0.3);
    brush.vertex(i, 0);
    brush.vertex(i + 100, 0);
    brush.vertex(i + 200, 200);
    brush.vertex(i + 100, 200);
    brush.endShape(true);
  }

  // Inner circle
  for (let i = 0; i < 20; i++) {
    brush.beginShape(0.3);
    brush.vertex(i + 100, 0);
    brush.vertex(i + 120, 200);
    brush.vertex(i + 140, 200);
    brush.vertex(i + 160, 200);
    brush.vertex(i + 180, 200);
    brush.vertex(i + 160, 180);
    brush.vertex(i + 140, 180);
    brush.vertex(i + 120, 180);
    brush.vertex(i + 100, 180);
    brush.endShape(true);
  }

  // Flowers
  let numFlowers = 10;
  for (let i = 0; i < numFlowers; i++) {
    let angle = i * Math.PI / 100;
    let radius = 10 + 2 * Math.sin(angle);
    brush.circle(200, 150 - radius, radius);
  }
}

