  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Define the moon's properties
  const moonX = 200;
  const moonY = 200;
  const moonRadius = 150;
  const moonColor = "#e08a72";
  const moonBrightness = 180;

  // Draw the moon
  brush.beginShape(0.3);
  brush.vertex(moonX, moonY);
  brush.vertex(moonX + moonRadius, moonY);
  brush.vertex(moonX + moonRadius * 2, moonY + moonRadius);
  brush.vertex(moonX, moonY + moonRadius * 2);
  brush.endShape(true);

  // Add a sea element
  brush.beginShape(0.3);
  brush.vertex(200, 200);
  brush.vertex(200 + moonRadius, 200);
  brush.vertex(200 + moonRadius * 2, 200);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Add details
  // Add the sun
  brush.beginShape(0.3);
  brush.vertex(200, 200);
  brush.vertex(200 + moonRadius, 200);
  brush.vertex(200 + moonRadius * 2, 200);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Add stars
  const starWidth = 10;
  const starHeight = 30;
  const starSpacing = 10;
  for (let i = 0; i < 30; i++) {
    const x = (i * starSpacing) + 200;
    const y = (i * starSpacing) + 200;
    brush.beginShape(0.3);
    brush.vertex(x, y);
    brush.vertex(x - starWidth, y - starHeight);
    brush.vertex(x + starWidth, y - starHeight);
    brush.vertex(x, y - starHeight);
    brush.endShape(true);
  }

  // Add stars in the moon
  const moonStarWidth = 10;
  const moonStarHeight = 30;
  const moonStarSpacing = 10;
  for (let i = 0; i < 30; i++) {
    const x = moonX + moonStarSpacing * 200;
    const y = moonY + moonStarSpacing * 200;
    brush.beginShape(0.3);
    brush.vertex(x, y);
    brush.vertex(x - moonStarWidth, y - moonStarHeight);
    brush.vertex(x + moonStarWidth, y - moonStarHeight);
    brush.vertex(x, y - moonStarHeight);
    brush.endShape(true);
  }
}

