function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Moon
  let moonX = 200;
  let moonY = 200;
  let moonRadius = 150;

  // Draw a full moon at night
  brush.beginShape(0);
  brush.vertex(moonX, moonY);
  brush.vertex(moonX + moonRadius * cos(0), moonY + moonRadius * sin(0));
  brush.vertex(moonX + moonRadius * cos(M_PI), moonY + moonRadius * sin(M_PI));
  brush.vertex(moonX + moonRadius * cos(2 * M_PI), moonY + moonRadius * sin(2 * M_PI));
  brush.vertex(moonX + moonRadius * cos(3 * M_PI), moonY + moonRadius * sin(3 * M_PI));
  brush.vertex(moonX + moonRadius * cos(4 * M_PI), moonY + moonRadius * sin(4 * M_PI));
  brush.endShape(true);

  // Sea
  let seaX = 200;
  let seaY = 200;
  let seaRadius = 200;

  // Draw a blue wash covering the sea
  brush.beginShape(0);
  brush.vertex(seaX, seaY);
  brush.vertex(seaX - seaRadius * cos(0), seaY - seaRadius * sin(0));
  brush.vertex(seaX - seaRadius * cos(M_PI), seaY - seaRadius * sin(M_PI));
  brush.vertex(seaX - seaRadius * cos(2 * M_PI), seaY - seaRadius * sin(2 * M_PI));
  brush.vertex(seaX - seaRadius * cos(3 * M_PI), seaY - seaRadius * sin(3 * M_PI));
  brush.vertex(seaX - seaRadius * cos(4 * M_PI), seaY - seaRadius * sin(4 * M_PI));
  brush.vertex(seaX, seaY - seaRadius * cos(0));
  brush.vertex(seaX, seaY - seaRadius * cos(M_PI));
  brush.vertex(seaX, seaY - seaRadius * cos(2 * M_PI));
  brush.vertex(seaX, seaY - seaRadius * cos(3 * M_PI));
  brush.vertex(seaX, seaY - seaRadius * cos(4 * M_PI));
  brush.endShape(true);

  // Night sky
  let skyX = 200;
  let skyY = 200;
  let skyRadius = 300;

  // Draw a dark sky effect
  brush.beginShape(0);
  brush.vertex(skyX, skyY);
  brush.vertex(skyX - skyRadius * cos(0), skyY - skyRadius * sin(0));
  brush.vertex(skyX - skyRadius * cos(M_PI), skyY - skyRadius * sin(M_PI));
  brush.vertex(skyX - skyRadius * cos(2 * M_PI), skyY - skyRadius * sin(2 * M_PI));
  brush.vertex(skyX - skyRadius * cos(3 * M_PI), skyY - skyRadius * sin(3 * M_PI));
  brush.vertex(skyX - skyRadius * cos(4 * M_PI), skyY - skyRadius * sin(4 * M_PI));
  brush.vertex(skyX, skyY - skyRadius * cos(0));
  brush.vertex(skyX, skyY - skyRadius * cos(M_PI));
  brush.vertex(skyX, skyY - skyRadius * cos(2 * M_PI));
  brush.vertex(skyX, skyY - skyRadius * cos(3 * M_PI));
  brush.vertex(skyX, skyY - skyRadius * cos(4 * M_PI));
  brush.endShape(true);
}

