    // Draw a small circle at the moon's position
    brush.circle(dx, dy, 5);
  }

  // Add some clouds and detail
  const cloudHeight = 100;
  const cloudOffset = 200;
  const cloudSpacing = 20;

  for (let i = 0; i < 30; i++) {
    const angle = i * cloudAngle;
    const dx = cloudOffset + cloudSpacing * Math.cos(angle);
    const dy = cloudOffset + cloudSpacing * Math.sin(angle);

    // Draw a small circle at the cloud's position
    brush.circle(dx, dy, 5);

    // Add some smoke
    brush.line(dx + 10, dy - 20, dx + 10, dy + 40);
    brush.line(dx - 10, dy - 20, dx - 10, dy + 40);
  }
}

