function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Function to calculate the brightness of a moon
  function moonBrightness(distance, radius) {
    return 0.05 * (distance / radius);
  }

  // Calculate the moon's position relative to the sea
  let moonPosition = createVector(0, 0);
  moonPosition.add(createVector(width / 2, height / 2));
  moonPosition.normalize();

  // Render the full moon
  brush.fillTexture(0.5, 0.4);
  brush.fill("#c9c9c9", moonBrightness(moonPosition.distance(0, 400), 200));
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", moonBrightness(moonPosition.distance(0, 400), 220));
  brush.circle(200, 150, 60);

  // Position the moon to be above the sea
  moonPosition.y += 40;
  moonPosition.x += 20;

  // Render the moon above the sea
  brush.fillTexture(0.5, 0.4);
  brush.fill("#c9c9c9", moonBrightness(moonPosition.distance(0, 400), 200));
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", moonBrightness(moonPosition.distance(0, 400), 220));
  brush.circle(200, 150, 60);

  // Position the moon to be behind the sea
  moonPosition.y -= 40;
  moonPosition.x -= 20;

  // Render the moon behind the sea
  brush.fillTexture(0.5, 0.4);
  brush.fill("#c9c9c9", moonBrightness(moonPosition.distance(0, 400), 200));
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", moonBrightness(moonPosition.distance(0, 400), 220));
  brush.circle(200, 150, 60);
}

function moonBrightness(distance, radius) {
  return 0.05 * (distance / radius);
}

