function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Define the moon's position and radius
  const moonX = 300;
  const moonY = 200;
  const moonRadius = 80;

  // Fill the moon with the color of the sun
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);

  // Draw the moon's central arc
  brush.beginPath();
  brush.arc(moonX, moonY, moonRadius, 0, Math.PI * 2);
  brush.endShape(true);

  // Draw the moon's shadow
  brush.noStroke();
  brush.beginShape(0.3);
  brush.arc(moonX, moonY, moonRadius / 2, 0, Math.PI * 2);
  brush.endShape(true);

  // Draw the moon's outlines
  brush.strokeWeight(1);
  brush.line(moonX, moonY, moonX + moonRadius, moonY);
  brush.line(moonX + moonRadius, moonY, moonX, moonY - moonRadius);
  brush.line(moonX, moonY - moonRadius, moonX - moonRadius, moonY - moonRadius);
  brush.line(moonX - moonRadius, moonY - moonRadius, moonX - moonRadius, moonY);
}

