function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Create a mist effect
  fill(255, 255, 255); // Mist color
  strokeWeight(2); // Mist thickness
  strokeCap(CAP_ROUND); // Mist corners

  // Draw the forest structure
  const forestWidth = 600;
  for (let i = 0; i < forestWidth; i++) {
    const height = getRandomInt(20, 50); // Height between 20 and 50
    const x = i * 400;
    const y = height * 400;

    // Draw the tree trunk
    stroke(0);
    fill(255, 0, 0);
    triangle(x, y - 50, x + 50, y - 50, x + 50, y);

    // Draw the tree leaves
    for (let j = 0; j < 5; j++) {
      const angle = Math.random() * 360;
      const offsetX = Math.sin(angle) * 5;
      const offsetY = Math.cos(angle) * 5;

      const leafX = x + offsetX;
      const leafY = y + offsetY;

      stroke(0);
      fill(255, 255, 255);
      circle(leafX, leafY, 10);
    }
  }

  // Draw the ground
  const groundHeight = 400;
  const groundX = width / 2;
  const groundY = height / 2;

  stroke(255, 255, 255);
  fill(255, 255, 255);
  rect(groundX - 50, groundY - 50, 100, 100);

  // Draw the leaves on the ground
  const leafRadius = 10;
  for (let j = 0; j < 5; j++) {
    const angle = Math.random() * 360;
    const offsetX = Math.sin(angle) * leafRadius;
    const offsetY = Math.cos(angle) * leafRadius;

    const leafX = groundX + offsetX;
    const leafY = groundY + offsetY;

    stroke(0);
    fill(255, 255, 255);
    circle(leafX, leafY, leafRadius);
  }

  // Draw the details
  for (let i = 0; i < 10; i++) {
    const detailHeight = getRandomInt(20, 50);
    const detailX = i * 400;
    const detailY = detailHeight * 400;

    stroke(0);
    fill(255, 255, 255);
    triangle(detailX, detailY - 50, detailX + 50, detailY - 50, detailX + 50, detailY);

    for (let j = 0; j < 5; j++) {
      const angle = Math.random() * 360;
      const offsetX = Math.sin(angle) * detailRadius;
      const offsetY = Math.cos(angle) * detailRadius;

      const detailLeafX = detailX + offsetX;
      const detailLeafY = detailY + offsetY;

      stroke(0);
      fill(255, 255, 255);
      circle(detailLeafX, detailLeafY, detailRadius);
    }
  }
}

