  brush.circle(centerX + 50, centerY - 50, 20);

  // Draw the tree
  brush.circle(centerX, centerY, 30);

  // Draw the leaves
  brush.circle(centerX - 20, centerY + 20, 20);
  brush.circle(centerX + 20, centerY + 20, 20);

  // Draw the branches
  for (let i = 0; i < 5; i++) {
    let angle = i * Math.PI / 5;
    brush.circle(centerX - 10, centerY + 20 + 20 * Math.cos(angle), 20);
    brush.circle(centerX + 10, centerY + 20 + 20 * Math.cos(angle), 20);
  }
}

