function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();

  // Forest background
  brush.fillStyle("white");
  brush.rect(0, 0, width, height);

  // Branches
  for (let i = 0; i < 5; i++) {
    brush.beginPath();
    brush.moveTo(width / 2 + i * 20, height - 50);
    brush.lineTo(width / 2 + 10 * i, height - 50);
    brush.lineTo(width / 2 + 20 * i, height - 50);
    brush.lineTo(width / 2 + 30 * i, height - 50);
    brush.lineTo(width / 2 + i * 20, height - 70);
    brush.closePath();
    brush.stroke();

    // Branch fill
    brush.fillStyle("#f0f0f0");
    brush.beginPath();
    brush.moveTo(width / 2 + i * 20, height - 65);
    brush.lineTo(width / 2 + 10 * i, height - 65);
    brush.lineTo(width / 2 + 20 * i, height - 65);
    brush.lineTo(width / 2 + 30 * i, height - 65);
    brush.lineTo(width / 2 + i * 20, height - 90);
    brush.closePath();
    brush.fill();

    // Branch border
    brush.lineWidth(1);
    brush.strokeStyle("#000000");
    brush.beginPath();
    brush.moveTo(width / 2 + i * 20, height - 50);
    brush.lineTo(width / 2 + 10 * i, height - 50);
    brush.lineTo(width / 2 + 20 * i, height - 50);
    brush.lineTo(width / 2 + 30 * i, height - 50);
    brush.lineTo(width / 2 + i * 20, height - 70);
    brush.closePath();
    brush.stroke();
  }
}

