function hotAirBalloon(x, y, radius) {
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);

  // Draw background
  brush.circle(x + radius / 2, y + radius / 2, radius);

  // Draw hot air balloon
  brush.circle(x, y, radius);
  brush.circle(x + radius / 2, y, radius * 2);

  // Draw surface
  brush.circle(x, y + radius / 2, radius * 2);
  brush.circle(x + radius / 2, y + radius * 2, radius * 3);

  // Draw eyes
  brush.circle(x, y + radius * 2 - 25, radius * 2);
  brush.circle(x, y + radius * 2 + 25, radius * 2);

  // Draw nose
  brush.circle(x, y + radius * 2 + 30, radius * 2);

  // Draw mouth
  brush.circle(x, y + radius * 2 + 35, radius * 2);

  // Draw whiskers
  brush.circle(x, y + radius * 2 + 40, radius * 2);
  brush.circle(x, y + radius * 2 + 45, radius * 2);

  // Draw hair
  brush.circle(x, y + radius * 2 + 50, radius * 2);
  brush.circle(x, y + radius * 2 + 55, radius * 2);
  brush.circle(x, y + radius * 2 + 60, radius * 2);

  // Draw tongue
  brush.circle(x, y + radius * 2 + 65, radius * 2);

  // Draw tail
  brush.circle(x, y + radius * 2 + 70, radius * 2);
  brush.circle(x, y + radius * 2 + 75, radius * 2);

  // Draw cloud
  brush.circle(x, y + radius * 2 + 80, radius * 2);
  brush.circle(x, y + radius * 2 + 85, radius * 2);
  brush.circle(x, y + radius * 2 + 90, radius * 2);
}

