function setup() {
  createCanvas(400, 400, WEBGL);
  background("#f4efe4");
  // Create a texture for the farmland
  var farmlandTexture = loadImage("farmland.jpg");

  // Define balloon properties
  var balloonRadius = 200;
  var balloonHeight = 150;
  var balloonSpeed = 10;
  var balloonFlapSpeed = 10;

  // Calculate the balloon's position on the texture
  var balloonPosition = getBalloonPosition(farmlandTexture);

  // Function to get the balloon's position on the texture
  function getBalloonPosition(texture) {
    var centerX = texture.width / 2;
    var centerY = texture.height / 2;
    var balloonX = centerX + balloonPosition.x;
    var balloonY = centerY + balloonPosition.y;
    return { x: balloonX, y: balloonY };
  }
}

function draw() {
  background("#f4efe4");

  // Load the farmland texture
  var farmlandTexture = loadImage("farmland.jpg");

  // Draw the farmland
  var farmlandWidth = farmlandTexture.width;
  var farmlandHeight = farmlandTexture.height;
  var farmlandX = width / 2;
  var farmlandY = height / 2;
  var farmlandScale = min(width, height) / 500;

  fill(farmlandTexture);
  rect(farmlandX, farmlandY, farmlandWidth * farmlandScale, farmlandHeight * farmlandScale);

  // Draw the balloon
  var balloonPosition = getBalloonPosition(farmlandTexture);
  var balloonX = balloonPosition.x + balloonRadius;
  var balloonY = balloonPosition.y + balloonHeight - balloonSpeed;
  var balloonRadius = balloonRadius - balloonSpeed;

  fill("#8a72");
  circle(balloonX, balloonY, balloonRadius);

  // Draw the balloon's flapping
  var flapPosition = getBalloonPosition(farmlandTexture);
  var flapX = balloonPosition.x + balloonRadius * 2;
  var flapY = balloonPosition.y + balloonHeight - balloonSpeed;
  var flapRadius = balloonRadius * 2;

  fill("#f2d9");
  circle(flapX, flapY, flapRadius);

  // Add lighting to simulate the hot air balloon's effect
  pushMatrix();
  rotate(radians(balloonFlapSpeed));
  tint(255, 255, 255, 180);
  ellipse(0, 0, 100, 100);
  popMatrix();
}

